create or replace function private.validate_teaching_document(payload jsonb,target uuid,term integer) returns void language plpgsql security definer set search_path='' as $$
begin
if payload is null or octet_length(payload::text)>1500000 or not extensions.jsonb_matches_schema($schema${"$schema":"http://json-schema.org/draft-07/schema#","type":"object","properties":{"lesson_status":{"type":"string","enum":["작성 중","검토 중","확정"]},"report":{"type":"object","properties":{"weekly_hours":{"anyOf":[{"type":"number","minimum":0,"maximum":10000},{"type":"null"}]},"format":{"type":"object","properties":{"version":{"type":"number","const":1},"name":{"type":"string","minLength":1,"maxLength":160},"lesson_title":{"type":"string","minLength":1,"maxLength":160},"assessment_title":{"type":"string","minLength":1,"maxLength":160},"lesson_orientation":{"type":"string","enum":["landscape","portrait"]},"assessment_orientation":{"type":"string","enum":["landscape","portrait"]},"lesson_columns":{"minItems":11,"maxItems":11,"type":"array","items":{"type":"object","properties":{"key":{"type":"string","enum":["month","week","day","title","standards","content","method","assessment_method","alignment","note","lessons"]},"label":{"type":"string","minLength":1,"maxLength":160},"enabled":{"type":"boolean"},"width":{"type":"integer","minimum":1,"maximum":100}},"required":["key","label","enabled","width"],"additionalProperties":false}},"sections":{"minItems":7,"maxItems":7,"type":"array","items":{"type":"object","properties":{"key":{"type":"string","enum":["purpose","policy","criteria","semester_levels","overview","details","additional"]},"title":{"type":"string","minLength":1,"maxLength":160},"enabled":{"type":"boolean"}},"required":["key","title","enabled"],"additionalProperties":false}},"footer":{"type":"string","maxLength":1000}},"required":["version","name","lesson_title","assessment_title","lesson_orientation","assessment_orientation","lesson_columns","sections","footer"],"additionalProperties":false}},"required":["weekly_hours","format"],"additionalProperties":false},"units":{"maxItems":500,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"period":{"type":"string","maxLength":100},"month":{"type":"string","maxLength":20},"week":{"type":"string","maxLength":40},"day":{"type":"string","maxLength":100},"assessment_method":{"type":"string","maxLength":2000},"start":{"anyOf":[{"type":"string","const":""},{"type":"string","format":"date","pattern":"^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))$"}]},"end":{"anyOf":[{"type":"string","const":""},{"type":"string","format":"date","pattern":"^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))$"}]},"title":{"type":"string","maxLength":200},"content":{"type":"string","maxLength":5000},"standard_ids":{"maxItems":50,"type":"array","items":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"}},"lessons":{"anyOf":[{"type":"number","minimum":0,"maximum":10000},{"type":"null"}]},"method":{"type":"string","maxLength":1000},"alignment":{"type":"string","maxLength":2000},"note":{"type":"string","maxLength":2000}},"required":["id","period","start","end","title","content","standard_ids","lessons","method","alignment","note"],"additionalProperties":false}},"evaluations":{"minItems":1,"maxItems":2,"type":"array","items":{"type":"object","properties":{"semester":{"type":"integer","minimum":1,"maximum":2},"mode":{"type":"string","enum":["weighted","descriptive"]},"status":{"type":"string","enum":["작성 중","검토 중","확정"]},"notes":{"type":"string","maxLength":5000},"detail":{"type":"object","properties":{"purpose":{"type":"string","maxLength":15000},"direction":{"type":"string","maxLength":15000},"policy":{"type":"string","maxLength":15000},"absence_policy":{"type":"string","maxLength":15000},"score_bands":{"maxItems":30,"type":"array","items":{"type":"object","properties":{"label":{"type":"string","maxLength":160},"description":{"type":"string","maxLength":10000}},"required":["label","description"],"additionalProperties":false}},"semester_levels":{"maxItems":30,"type":"array","items":{"type":"object","properties":{"label":{"type":"string","maxLength":160},"description":{"type":"string","maxLength":10000}},"required":["label","description"],"additionalProperties":false}},"additional":{"maxItems":30,"type":"array","items":{"type":"object","properties":{"label":{"type":"string","maxLength":160},"description":{"type":"string","maxLength":10000}},"required":["label","description"],"additionalProperties":false}}},"required":["purpose","direction","policy","absence_policy","score_bands","semester_levels","additional"],"additionalProperties":false},"items":{"maxItems":200,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"type":{"type":"string","enum":["정기시험","수행평가","기타"]},"name":{"type":"string","maxLength":200},"element":{"type":"string","maxLength":3000},"standard_ids":{"maxItems":50,"type":"array","items":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"}},"method":{"type":"string","maxLength":2000},"period":{"type":"string","maxLength":100},"start":{"anyOf":[{"type":"string","const":""},{"type":"string","format":"date","pattern":"^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))$"}]},"end":{"anyOf":[{"type":"string","const":""},{"type":"string","format":"date","pattern":"^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))$"}]},"count":{"anyOf":[{"type":"integer","minimum":1,"maximum":100},{"type":"null"}]},"ratio":{"anyOf":[{"type":"number","minimum":0,"maximum":100},{"type":"null"}]},"points":{"anyOf":[{"type":"number","minimum":0,"maximum":10000},{"type":"null"}]},"rubric":{"maxItems":100,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"element":{"type":"string","maxLength":200},"points":{"anyOf":[{"type":"number","minimum":0,"maximum":10000},{"type":"null"}]},"levels":{"maxItems":50,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"label":{"type":"string","maxLength":100},"description":{"type":"string","maxLength":3000},"points":{"anyOf":[{"type":"number","minimum":0,"maximum":10000},{"type":"null"}]}},"required":["id","label","description","points"],"additionalProperties":false}},"note":{"type":"string","maxLength":1000}},"required":["id","element","points","levels","note"],"additionalProperties":false}},"notes":{"type":"string","maxLength":3000},"detail":{"type":"object","properties":{"lessons":{"anyOf":[{"type":"number","minimum":0,"maximum":10000},{"type":"null"}]},"unit_content":{"type":"string","maxLength":3000},"methods":{"type":"string","maxLength":2000},"competencies":{"type":"string","maxLength":2000},"standard_levels":{"maxItems":50,"type":"array","items":{"type":"object","properties":{"label":{"type":"string","maxLength":160},"description":{"type":"string","maxLength":10000}},"required":["label","description"],"additionalProperties":false}}},"required":["lessons","unit_content","methods","competencies","standard_levels"],"additionalProperties":false}},"required":["id","type","name","element","standard_ids","method","period","start","end","count","ratio","points","rubric","notes"],"additionalProperties":false}}},"required":["semester","mode","status","notes","items"],"additionalProperties":false}}},"required":["lesson_status","units","evaluations"],"additionalProperties":false}$schema$::json,payload) then raise exception '계획 입력 형식과 크기를 확인해 주세요.';end if;
 if payload ? 'report' and (
 (select count(distinct v->>'key') from jsonb_array_elements(payload#>'{report,format,lesson_columns}') v)<>11
 or (select count(distinct v->>'key') from jsonb_array_elements(payload#>'{report,format,sections}') v)<>7
 or not exists(select 1 from jsonb_array_elements(payload#>'{report,format,lesson_columns}') v where (v->>'enabled')::boolean)
 or not exists(select 1 from jsonb_array_elements(payload#>'{report,format,sections}') v where (v->>'enabled')::boolean)
 ) then raise exception '출력 서식의 열·항목 구성을 확인하세요.'; end if;
 if (term=0 and ((select count(distinct (e->>'semester')::integer) from jsonb_array_elements(payload->'evaluations') e)<>2))
 or (term<>0 and (jsonb_array_length(payload->'evaluations')<>1 or (payload->'evaluations'->0->>'semester')::integer<>term)) then raise exception '수업과 평가 학기를 확인해 주세요.';end if;
 if exists(select 1 from jsonb_array_elements(payload->'units') e group by e->>'id' having count(*)>1)
 or exists(select 1 from jsonb_array_elements(payload->'evaluations') ev cross join lateral jsonb_array_elements(ev->'items') e group by e->>'id' having count(*)>1) then raise exception '단원·평가 항목 ID가 중복됩니다.';end if;
 if exists(select 1 from (
 select s.value::uuid id from jsonb_array_elements(payload->'units') u cross join lateral jsonb_array_elements_text(u->'standard_ids') s
 union select s.value::uuid from jsonb_array_elements(payload->'evaluations') ev cross join lateral jsonb_array_elements(ev->'items') a cross join lateral jsonb_array_elements_text(a->'standard_ids') s
 ) linked where not exists(select 1 from public.achievement_standards st where st.id=linked.id and st.workspace_id=target)) then raise exception '다른 작업공간의 성취기준을 연결할 수 없습니다.' using errcode='42501';end if;
end $$;
create or replace function private.save_teaching_plan(target_course uuid,expected_version integer,payload jsonb,confirm_plan boolean default false) returns integer language plpgsql security definer set search_path='' as $$
declare c public.teaching_courses; old_doc jsonb; doc jsonb:=payload;
begin
 if not private.teaching_access(target_course,true) then raise exception '이 계획의 편집 권한이 없습니다.' using errcode='42501';end if;
 select * into c from public.teaching_courses where id=target_course for update;
 if c.version is distinct from expected_version or c.archived then raise exception '계획이 변경되었거나 보관되었습니다. 새로고침 후 확인해 주세요.';end if;
 perform private.validate_teaching_document(payload,c.workspace_id,c.semester);
 select document into old_doc from public.teaching_plans where course_id=target_course;
 if not coalesce(confirm_plan,false) then
  if old_doc->>'lesson_status'='확정' and (old_doc->'units' is distinct from doc->'units' or old_doc->'report' is distinct from doc->'report') then doc:=jsonb_set(doc,'{lesson_status}','"작성 중"');end if;
  doc:=jsonb_set(doc,'{evaluations}',(select jsonb_agg(case when exists(select 1 from jsonb_array_elements(old_doc->'evaluations') old where old->>'semester'=ev->>'semester' and old->>'status'='확정' and ((old-'status') is distinct from (ev-'status') or old_doc->'report' is distinct from doc->'report')) then jsonb_set(ev,'{status}','"작성 중"') else ev end order by ord) from jsonb_array_elements(doc->'evaluations') with ordinality a(ev,ord)));
 end if;
 update public.teaching_plans set document=doc where course_id=target_course;
 perform private.teaching_replace_links(target_course,c.workspace_id,doc);
 update public.teaching_courses set version=version+1,updated_at=now() where id=target_course;
 perform private.teaching_record_revision(target_course,case when confirm_plan then '상태 확인 후 저장' else '계획 저장' end);
 return c.version+1;
end $$;
commit;
